css:
.uv-ti {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ti {
  display: inline-block;
  font-size: var(--s);
  cursor: pointer;
}

.uv-ti input {
  display: none;
}

.uv-ti span {
  position: relative;
  display: block;
  width: 3.2em;
  height: 1.9em;
  border-radius: 999px;
  background: color-mix(in srgb,var(--fg) 18%,transparent);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ti span::after {
  content: "";
  position: absolute;
  left: .15em;
  top: .15em;
  width: 1.6em;
  height: 1.6em;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 2px 6px rgba(0,0,0,.25);
  transition: all calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ti:active span::after {
  width: 2.1em;
}

.uv-ti input:checked+span {
  background: var(--c1);
}

.uv-ti input:checked+span::after {
  left: calc(100% - 1.75em);
}

.uv-ti:active input:checked+span::after {
  left: calc(100% - 2.25em);
}

