css:
.uv-dn {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-dn {
  display: inline-block;
  font-size: var(--s);
  cursor: pointer;
}

.uv-dn input {
  display: none;
}

.uv-dn span {
  position: relative;
  display: block;
  width: 4.4em;
  height: 2.2em;
  overflow: hidden;
  border-radius: 999px;
  background: linear-gradient(#7dd3fc,#3b82f6);
  box-shadow: inset 0 2px 6px rgba(0,0,0,.2);
  transition: background calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-dn i {
  position: absolute;
  left: .25em;
  top: .25em;
  width: 1.7em;
  height: 1.7em;
  border-radius: 50%;
  background: #fcd34d;
  box-shadow: 0 0 .8em #fde68a,inset -.15em -.15em 0 #f59e0b;
  transition: all calc(0.6s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-dn b {
  position: absolute;
  width: .18em;
  height: .18em;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transform: translateY(.6em);
  transition: all calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-dn b:nth-of-type(1) {
  left: .9em;
  top: .5em;
}

.uv-dn b:nth-of-type(2) {
  left: 1.6em;
  top: 1.3em;
  transition-delay: calc(0.1s / var(--k));
}

.uv-dn b:nth-of-type(3) {
  left: 2.1em;
  top: .6em;
  transition-delay: calc(0.2s / var(--k));
}

.uv-dn input:checked+span {
  background: linear-gradient(#0f172a,#312e81);
}

.uv-dn input:checked+span i {
  left: calc(100% - 1.95em);
  background: #e2e8f0;
  box-shadow: 0 0 .6em rgba(226,232,240,.5),inset -.5em -.1em 0 #94a3b8;
}

.uv-dn input:checked+span b {
  opacity: 1;
  transform: none;
}

