  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  display: inline-block;
  font-size: var(--s);
  cursor: pointer;
}

.uv-tt input {
  display: none;
}

.uv-tt span {
  position: relative;
  display: block;
  width: 4.2em;
  height: 2em;
  overflow: hidden;
  border-radius: 999px;
