.uv-tt input:checked+span::after {
  transform: translateX(2.2em);
}

.uv-tt input:checked+span em:first-child {
  transform: none;
  opacity: 1;
}

.uv-tt input:checked+span em:last-child {
  transform: translateX(2em);
  opacity: 0;
}

