  position: relative;
  display: inline-flex;
  align-items: center;
  gap: .8em;
  cursor: pointer;
  user-select: none;
  font-weight: 550;
}

.uv-tap input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uv-tap .tr {
  position: relative;
  display: block;
  width: 4em;
  height: 2.1em;
  border-radius: 1.05em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 14%,transparent);
  transition: background calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

