  position: absolute;
  height: .32em;
  border-radius: 1em;
  background: #fff;
  opacity: 0;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-tap .cl.a {
  top: .45em;
  width: .9em;
  left: 100%;
}

.uv-tap .cl.b {
  top: 1.3em;
  width: .6em;
  left: 100%;
}

.uv-tap .kn {
  position: absolute;
  left: .2em;
  top: .2em;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.7em;
  border-radius: 50%;
  color: color-mix(in srgb,var(--fg) 55%,#888);
  background: #fff;
  box-shadow: 0 .15em .4em rgba(0,0,0,.22);
  transition: left calc(0.6s / var(--k)) cubic-bezier(.22,1,.36,1),color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
