  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq03-pcd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: .8em;
  cursor: pointer;
  user-select: none;
  font-weight: 550;
}

.uvq03-pcd input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uvq03-pcd .lm {
  position: relative;
  display: block;
  flex: none;
  width: 4em;
  height: 5em;
  border-radius: .6em;
}

.uvq03-pcd .lm i {
  position: absolute;
  display: block;
}

.uvq03-pcd .cb {
  left: 50%;
  top: 0;
  width: .08em;
  height: 1.05em;
  margin-left: -.04em;
  background: color-mix(in srgb,var(--fg) 55%,transparent);
}

