}

.uvq03-pcd .bu {
  left: 50%;
  top: 2.1em;
  width: .8em;
  height: .45em;
  margin-left: -.4em;
  border-radius: 0 0 .4em .4em;
  background: #e6e1d6;
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq03-pcd .cn {
  left: -.2em;
  right: -.2em;
