  opacity: 0;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq03-pcd .cd {
  position: absolute;
  left: 2.95em;
  top: 2.15em;
  width: .7em;
