  cursor: grab;
  transition: height calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq03-pcd .cd::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: .4em;
  width: .05em;
  margin-left: -.025em;
  background: #9a9284;
}

.uvq03-pcd .bd {
  left: 50%;
  bottom: 0;
